import { writeFileSync, readFileSync } from 'node:fs';
import { NumericTypes } from '../numeric-types.js';

// Emit source, rather than building closures or decoding selectors at runtime.
const lines = [
  '// Generated by node hg/tools/generate-swizzles.mjs. Do not edit by hand.',
  "import { Data } from './data.js';",
  '',
  'const __swizzleAccessors__ = Object.assign(Object.create(null), {',
];
for (const type of NumericTypes.vectorTypes) {
  const { size, scalar, suffix } = NumericTypes.vectorInfo(type);
  const letters = 'xyzw'.slice(0, size);
  lines.push(`  ${type}: Object.assign(Object.create(null), {`);
  let names = [''];
  for (let length = 1; length <= 4; length++) {
    names = names.flatMap((prefix) => [...letters].map((letter) => prefix + letter));
    for (const name of names) {
      const indices = [...name].map((letter) => 'xyzw'.indexOf(letter));
      const components = indices.map((index) => `Data.component(v, ${index})`).join(', ');
      const resultType = length === 1 ? scalar : `vec${length}${suffix}`;
      const read =
        length === 1 ? components : `Data.numericFromComponents('${resultType}', [${components}])`;
      const write =
        new Set(name).size === length
          ? `, write: (v, values) => { ${indices.map((index, i) => `Data.put(v, ${index}, values[${i}]);`).join(' ')} }`
          : '';
      lines.push(`    ${name}: { read: v => ${read}, replacementType: '${resultType}'${write} },`);
    }
  }
  lines.push('  }),');
}
lines.push(
  '});',
  '',
  'const __swizzleNames__ = new Set(Object.keys(__swizzleAccessors__.vec4f));',
  'const __writableSwizzleNames__ = new Set(Object.keys(__swizzleAccessors__.vec4f).filter(name => __swizzleAccessors__.vec4f[name].write));',
  '',
);
lines.push(
  'export const Swizzles = { accessors: __swizzleAccessors__, names: __swizzleNames__, writableNames: __writableSwizzleNames__ };',
  '',
);
const source = lines.join('\n');
const destination = new URL('../swizzles.generated.js', import.meta.url);
if (process.argv.includes('--check')) {
  if (readFileSync(destination, 'utf8').replace(/\r\n/g, '\n') !== source) {
    throw new Error('Generated swizzles are stale; run node hg/tools/generate-swizzles.mjs');
  }
} else {
  writeFileSync(destination, source);
}
